INSERT INTO repository_attachments (attachment_id, workspace_id, repository_reference, router_time, time_basis, origin_installation, origin_machine, import_digest) VALUES (?1, ?2, ?3, json_extract(?4, '$.time.value'), CASE json_extract(?4, '$.time.kind') WHEN 'router' THEN 'router' WHEN 'legacyUnknown' THEN 'legacy_unknown' END, json_extract(?4, '$.origin.installation'), json_extract(?4, '$.origin.machine'), ?5) ON CONFLICT(workspace_id, repository_reference) DO NOTHING;
